// Wholly original metre-model panels and resources. No GTA geometry or recordings.
import {canonical,byteDigest,staticWorldSchema} from '../../src/acoustics/world/contracts.mjs';
export const fixtureBounds={min:[-16,-12,-4],max:[16,12,12]};
export const panel=(id='wall')=>({id,center:[0,0,0],normal:[0,-1,0],u:[1,0,0],half:[12,4],openings:[]});
export const entity=(id='building',archetype='wall',position=[0,4,3])=>({id,archetype,position,rotation:[0,0,0,1],scale:1,interior:'exterior-fixture'});
export function resource(id,role,payload,{path=id+'.json',order=0,scopeTiles=null,format=staticWorldSchema,deleted=false}={}){const bytes=Buffer.from(canonical({schema:1,format:staticWorldSchema,origin:'original-authored-fixture',role,...payload}));return {entry:{id,path,order,format,role,sha256:byteDigest(bytes),bytes:bytes.length,scopeTiles,deleted},bytes};}
export function fixtureWorld(kind='wall',{moved=0,extraResources=[]}={}){const archetypes=resource('base-archetypes','archetypes',{archetypes:[{id:'wall',panels:[panel()],children:[]},{id:'tunnel',panels:[panel('side-a'),{...panel('side-b'),center:[0,-6,0]}],children:[]},{id:'interior-shell',panels:[],children:[entity('inner-wall','wall',[0,0,0])]}]}),entities=kind==='open'?[]:kind==='wall'?[entity('building','wall',[0,4+moved,3])]:kind==='passage'?[entity('south','wall',[0,-3,3]),entity('north','wall',[0,3,3])]:kind==='tunnel'?[entity('tunnel','tunnel',[0,3,3])]:[entity('interior','interior-shell',[0,4,3])],placements=resource('base-map','placements',{entities},{scopeTiles:['local']});return {input:{schema:1,build:'authored-build-1',mapFamily:'authored-map-fixture',mountPolicy:'explicit-fixture-order-v1',origin:'original-authored-fixture',resources:[archetypes.entry,placements.entry,...extraResources.map(r=>r.entry)]},resources:Object.fromEntries([archetypes,placements,...extraResources].map(r=>[r.entry.id,r.bytes])),tiles:[{tileId:'local',bounds:fixtureBounds},{tileId:'far',bounds:{min:[80,80,-4],max:[112,112,12]}}]};}
